/* 把主题里的引用数组解析成完整词条；库里缺失时保留原引用并告警 */
window.resolveWordRefs = function (refs) {
  return (refs || []).map((ref) => {
    const id = typeof ref === "string" ? ref : ref && ref.word;
    const base = window.DINO_WORD_LIBRARY[id];
    if (!base) { console.warn("[word-library] 词条缺失:", id); return typeof ref === "string" ? { word: ref } : { ...ref }; }
    return typeof ref === "string" ? { ...base } : { ...base, ...ref };
  });
};
/* 词性池：从总库按 category 重建（原 9 个词性文件已并入本库） */
window.DINO_WORD_SETS = window.DINO_WORD_SETS || [];
["noun", "verb", "adj", "adv", "pron", "prep", "conj", "interj", "num"].forEach(function (pos) {
  const words = [];
  for (const key in window.DINO_WORD_LIBRARY) {
    const w = window.DINO_WORD_LIBRARY[key];
    if (w.category === pos) words.push(Object.assign({}, w, { key: key }));
  }
  window.DINO_WORD_SETS.push({ id: pos, isPool: true, words: words });
});
